import{_ as n,C as r,o as l,c as h,j as e,a as t,E as o,ah as a}from"./chunks/framework.BpF7DVZ1.js";const v=JSON.parse('{"title":"差异视图","description":"","frontmatter":{},"headers":[],"relativePath":"components/diff-view.md","filePath":"components/diff-view.md","lastUpdated":1788635489000}'),f={name:"components/diff-view.md"},s={id:"差异视图",tabindex:"-1"};function p(g,d,u,b,w,x){const i=r("Badge"),c=r("XhDemo");return l(),h("div",null,[e("h1",s,[d[0]||(d[0]=t("差异视图 ",-1)),o(i,{type:"info",text:"diff-view"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#差异视图","aria-label":'Permalink to "差异视图 <Badge type="info" text="diff-view" />"'},"​",-1))]),d[3]||(d[3]=a('<p>一份改动的逐行呈现：并排或单栏、双侧行号、变更类型的读屏文字，以及远离变更处的折叠。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>展示 AI 提议的代码改动，或两版文本的对比。</li><li>手里有一份统一格式的补丁，或者有新旧两版全文。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只展示一段代码：用<a href="./code-view">代码视图</a>。</li><li>展示的是「AI 提议的数据编辑逐条取舍」：那是一张带多选的<a href="./table">表格</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>两个入口归一到同一个模型</strong>：<code>computeTextDiff(before, after)</code> 拿两版全文算， <code>parseUnifiedPatch(patch)</code> 解析补丁；组件只认模型。</li><li><strong>着色在建模时一次算好</strong>，不在连接层跑：<code>computeTextDiff</code> 手里有完整文本， 整体切一次再按行取，跨行的块注释与多行字符串才不会着错色。 <code>parseUnifiedPatch</code> 拿不到完整文件，因此<strong>一律不填着色</strong>——宁可不着色也不错着色。</li><li><strong>词级差异</strong>：配对的一条删除行与一条新增行之间再比一次词，只有真正动过的那几段上底色， 整行改写与超长行不比（比出来满行都在闪，等于没有重点）。两个入口都产出，<code>wordDiff: false</code> 关掉。</li><li><code>contextLines</code> 把 hunk 内远离变更的连续上下文折成一格，点开即展开。 展开集合可受控，好让「全部展开」这类操作统一持有。</li><li><code>wrap</code> 让长行原地折行，卡片不再横向滚动；窄栏与并排视图下尤其有用。</li><li>头部自带增删统计位 <code>summary</code>，增删各一个，数字取自模型、着色跟着变更类型走。</li><li><code>maxLines</code> 是必须有的上限：AI 会吐超大文件，新旧两侧各自超出即从尾部砍掉。 砍掉几行由模型带出来，<code>truncation</code> 提示条把这个数说给读的人。</li><li>行号与列号一律从模型算，<strong>绝不从 DOM 反推</strong>。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="单栏差异" tabindex="-1">单栏差异 <a class="header-anchor" href="#单栏差异" aria-label="Permalink to &quot;单栏差异&quot;">​</a></h3><p>两个入口归一到同一个模型：这里用新旧两版全文算，着色在建模时一次算好</p>',10)),o(c,{src:"diff-view/01-unified"}),d[4]||(d[4]=e("h3",{id:"并排与折叠",tabindex:"-1"},[t("并排与折叠 "),e("a",{class:"header-anchor",href:"#并排与折叠","aria-label":'Permalink to "并排与折叠"'},"​")],-1)),d[5]||(d[5]=e("p",null,"并排两列都发格子，空的那一侧照发；远离变更的连续上下文折成一格，点开即展开",-1)),o(c,{src:"diff-view/02-split-fold"}),d[6]||(d[6]=e("h3",{id:"长行换行与词级差异",tabindex:"-1"},[t("长行换行与词级差异 "),e("a",{class:"header-anchor",href:"#长行换行与词级差异","aria-label":'Permalink to "长行换行与词级差异"'},"​")],-1)),d[7]||(d[7]=e("p",null,"开 wrap 让长行原地折行；配对的删改行之间再比一次词，只有真正动过的那几段上底色",-1)),o(c,{src:"diff-view/03-wrap-words"}),d[8]||(d[8]=e("h3",{id:"超长差异的截断提示",tabindex:"-1"},[t("超长差异的截断提示 "),e("a",{class:"header-anchor",href:"#超长差异的截断提示","aria-label":'Permalink to "超长差异的截断提示"'},"​")],-1)),d[9]||(d[9]=e("p",null,"超过 maxLines 的部分被砍掉，提示条把砍了多少行说给读的人",-1)),o(c,{src:"diff-view/04-truncated"}),d[10]||(d[10]=e("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[11]||(d[11]=e("p",null,"size 换字号、行高与行号槽的宽度，三档并列对照",-1)),o(c,{src:"diff-view/05-size"}),d[12]||(d[12]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-diff-view&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhDiffViewBody</code> <code>XhDiffViewEmpty</code> <code>XhDiffViewHeader</code> <code>XhDiffViewRoot</code> <code>XhDiffViewSummary</code> <code>XhDiffViewTruncation</code> <code>XhDiffViewViewport</code></td></tr><tr><td>组合式函数</td><td><code>useDiffView</code></td></tr><tr><td>状态机</td><td><code>diffViewMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/diff-view.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;diff-view&quot;</code>：<strong><code>root</code></strong> · <code>header</code> · <code>summary</code> · <strong><code>viewport</code></strong> · <strong><code>body</code></strong> · <code>row</code> · <code>line-number</code> · <code>line-content</code> · <code>change-label</code> · <code>inline-change</code> · <code>token</code> · <code>gap</code> · <code>gap-cell</code> · <code>gap-trigger</code> · <code>empty</code> · <code>truncation</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>DiffModel</code></td><td></td><td>差异模型，唯一入口。补丁与新旧两版文本都先归一到它。</td></tr><tr><td><code>view</code></td><td><code>DiffViewMode</code></td><td></td><td></td></tr><tr><td><code>contextLines</code></td><td><code>number</code></td><td></td><td>变更两侧各露几行上下文，其余折起来；不给或非有限值即不折叠。</td></tr><tr><td><code>expandedValue</code></td><td><code>readonly string[]</code></td><td></td><td>展开的折叠格 id 集合，给了即受控。</td></tr><tr><td><code>defaultExpandedValue</code></td><td><code>readonly string[]</code></td><td></td><td></td></tr><tr><td><code>wrap</code></td><td><code>boolean</code></td><td></td><td>长行原地折行，不再横向滚动；默认关。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;DiffViewTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onExpandedValueChange</code></td><td><code>(details: DiffViewExpandedValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>expanded-value-change</code></td><td><code>DiffViewExpandedValueChangeDetails</code></td><td>展开集合变化；detail 为 <code>{ value: string[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhDiffViewRoot</code></td><td><code>default</code></td><td><code>DiffViewRootSlotProps</code></td><td></td></tr><tr><td><code>XhDiffViewSummary</code></td><td><code>default</code></td><td><code>{ count: number }</code></td><td></td></tr><tr><td><code>XhDiffViewTruncation</code></td><td><code>default</code></td><td><code>{ count: number }</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>GAP.EXPAND</code> · <code>GAP.COLLAPSE</code> · <code>CONTROLLED.EXPANDED.SET</code></p><p><strong>判据</strong>：<code>isExpandedControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useDiffView</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>view</code></td><td><code>DiffViewMode</code></td><td></td></tr><tr><td><code>rows</code></td><td><code>readonly DiffViewRow[]</code></td><td>折叠后的可见行序，含折起来的那些格。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>stats</code></td><td><code>{ added: number, removed: number }</code></td><td>增删各多少行。</td></tr><tr><td><code>truncated</code></td><td><code>boolean</code></td><td>模型被上限截断过。</td></tr><tr><td><code>truncatedLines</code></td><td><code>number</code></td><td>被上限砍掉、压根没进这份模型的源文本行数；没截断就是 0。</td></tr><tr><td><code>truncationText</code></td><td><code>string</code></td><td>截断提示条的文字，已把行数代进去；没截断时是空串。</td></tr><tr><td><code>isEmpty</code></td><td><code>boolean</code></td><td>一条变更都没有。</td></tr><tr><td><code>setExpandedValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>toggleGap</code></td><td><code>(id: string) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>(props: { change: DiffChange }) =&gt; T[&#39;element&#39;]</code></td><td>头部右侧的增删统计位，增删各一个。</td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBodyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRowProps</code></td><td><code>(props: DiffViewRowProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineNumberProps</code></td><td><code>(props: DiffViewCellProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineContentProps</code></td><td><code>(props: DiffViewCellProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getChangeLabelProps</code></td><td><code>(props: { change: DiffChange }) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getInlineChangeProps</code></td><td><code>(props: DiffViewInlineChangeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTokenProps</code></td><td><code>(token: CodeToken) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGapProps</code></td><td><code>(props: DiffViewGapProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGapCellProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGapTriggerProps</code></td><td><code>(props: DiffViewGapProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTruncationProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>截断提示条；没截断时带 hidden。</td></tr><tr><td><code>changeLabel</code></td><td><code>(change: DiffChange) =&gt; string</code></td><td>变更类型对应的读屏文字，写进视觉隐藏的那一格。</td></tr><tr><td><code>cellText</code></td><td><code>(props: DiffViewCellProps) =&gt; string | undefined</code></td><td>这一行在这一侧的文本；split 下空侧为 undefined。</td></tr><tr><td><code>cellNumber</code></td><td><code>(props: DiffViewCellProps) =&gt; number | undefined</code></td><td>这一行在这一侧的行号；没有就是 undefined。</td></tr><tr><td><code>cellTokens</code></td><td><code>(props: DiffViewCellProps) =&gt; readonly CodeToken[]</code></td><td>这一行在这一侧的着色片段；不着色或空侧时为空数组。</td></tr><tr><td><code>cellSegments</code></td><td><code>(props: DiffViewCellProps) =&gt; readonly DiffViewSegment[]</code></td><td>这一行在这一侧的词级片段，着色记号已按片段边界切好。 没算词级差异时为空数组，此时照 cellTokens / cellText 铺。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>差异视图在 Tab 序列中</td><td>滚动容器自身可聚焦，随后方向键的横纵滚动交给浏览器，组件不接管</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在展开按钮上</td><td>展开该处折起来的上下文行；组件只接 click，按键走原生 button 的默认行为</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>body</code></td><td><code>aria-colcount</code></td><td>2 | 1</td></tr><tr><td><code>body</code></td><td><code>aria-label</code></td><td>undefined | translations?.diff</td></tr><tr><td><code>body</code></td><td><code>aria-labelledby</code></td><td><code>header</code> 部件的 id | undefined</td></tr><tr><td><code>body</code></td><td><code>aria-rowcount</code></td><td>rows.length</td></tr><tr><td><code>body</code></td><td><code>role</code></td><td>&#39;table&#39;</td></tr><tr><td><code>row</code></td><td><code>aria-rowindex</code></td><td>rowIndex</td></tr><tr><td><code>row</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr><tr><td><code>line-number</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>line-content</code></td><td><code>aria-colindex</code></td><td>2 | 1</td></tr><tr><td><code>line-content</code></td><td><code>role</code></td><td>&#39;cell&#39;</td></tr><tr><td><code>gap</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr><tr><td><code>gap-cell</code></td><td><code>aria-colindex</code></td><td>1</td></tr><tr><td><code>gap-cell</code></td><td><code>role</code></td><td>&#39;cell&#39;</td></tr><tr><td><code>gap-trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>gap-trigger</code></td><td><code>aria-label</code></td><td>expandGapLabel(hiddenCountOf(gapId))</td></tr></tbody></table><ul><li>表格语义：<code>role=table</code> 配 <code>role=row</code> 与 <code>role=cell</code>，带 <code>aria-rowcount</code> / <code>aria-rowindex</code> / <code>aria-colcount</code> / <code>aria-colindex</code>。列数只数<strong>真正暴露的内容列</strong>——行号不算列。</li><li>每一行都带一段视觉隐藏的变更类型文字：<strong>变更不能只靠颜色传达</strong>。</li><li>变更行还有一条非颜色线索：新增画实心色条，删除画同宽的斜纹条，灰度与高对比度下也分得开。</li><li>行号对读屏隐藏，由皮肤用 <code>attr()</code> 画出来，因此复制差异不会带上行号。</li><li><strong>刻意不采表格那套行级 roving</strong>：只读差异不是网格，给每份差异一个吞方向键的焦点组 会把页面滚动抢走，而读屏本来就有表格浏览模式。这是显式裁决，不是遗漏。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/diff-view.css</code> 按部件选择：<code>[data-scope=&quot;diff-view&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-truncated</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-view</code></td><td>props.view</td></tr><tr><td><code>root</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>summary</code></td><td><code>data-change</code></td><td>change</td></tr><tr><td><code>row</code></td><td><code>data-change</code></td><td>lineAt(rowIndex)?.change</td></tr><tr><td><code>row</code></td><td><code>data-revealed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>line-number</code></td><td><code>data-change</code></td><td>lineAt(rowIndex)?.change</td></tr><tr><td><code>line-number</code></td><td><code>data-line-number</code></td><td>cellNumber({ rowIndex, side })?.toString()</td></tr><tr><td><code>line-number</code></td><td><code>data-side</code></td><td>side</td></tr><tr><td><code>line-content</code></td><td><code>data-change</code></td><td>lineAt(rowIndex)?.change</td></tr><tr><td><code>line-content</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>line-content</code></td><td><code>data-side</code></td><td>side</td></tr><tr><td><code>change-label</code></td><td><code>data-change</code></td><td>change</td></tr><tr><td><code>inline-change</code></td><td><code>data-change</code></td><td>lineAt(rowIndex)?.change | undefined</td></tr><tr><td><code>token</code></td><td><code>data-kind</code></td><td>token.kind</td></tr><tr><td><code>gap</code></td><td><code>data-expanded</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>gap</code></td><td><code>data-value</code></td><td>hunkIndex:0</td></tr><tr><td><code>gap-trigger</code></td><td><code>data-value</code></td><td>hunkIndex:0</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-diff-view-added-bg</code> · <code>--xh-diff-view-added-fg</code> · <code>--xh-diff-view-bg</code> · <code>--xh-diff-view-border</code> · <code>--xh-diff-view-change-bar</code> · <code>--xh-diff-view-comment-fg</code> · <code>--xh-diff-view-empty-bg</code> · <code>--xh-diff-view-empty-fg</code> · <code>--xh-diff-view-font</code> · <code>--xh-diff-view-font-size</code> · <code>--xh-diff-view-gap-bg</code> · <code>--xh-diff-view-gap-bg-hover</code> · <code>--xh-diff-view-gap-fg</code> · <code>--xh-diff-view-gutter</code> · <code>--xh-diff-view-header-fg</code> · <code>--xh-diff-view-header-font-size</code> · <code>--xh-diff-view-header-gap</code> · <code>--xh-diff-view-icon-size</code> · <code>--xh-diff-view-inline-change-radius</code> · <code>--xh-diff-view-keyword-fg</code> · <code>--xh-diff-view-keyword-weight</code> · <code>--xh-diff-view-line-height</code> · <code>--xh-diff-view-max-h</code> · <code>--xh-diff-view-number-fg</code> · <code>--xh-diff-view-number-token-fg</code> · <code>--xh-diff-view-punctuation-fg</code> · <code>--xh-diff-view-px</code> · <code>--xh-diff-view-py</code> · <code>--xh-diff-view-radius</code> · <code>--xh-diff-view-removed-bg</code> · <code>--xh-diff-view-removed-fg</code> · <code>--xh-diff-view-shadow</code> · <code>--xh-diff-view-string-fg</code> · <code>--xh-diff-view-truncation-bg</code> · <code>--xh-diff-view-truncation-border</code> · <code>--xh-diff-view-truncation-fg</code> · <code>--xh-diff-view-truncation-gap</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-diff-view-reveal</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>单栏与并排的切换用<a href="./toggle-group">开关组</a>；增删统计已有成品位，不必再自己拼 （只要数字不要版式时仍可用 <code>diffStats(model)</code>）。</li><li>装进<a href="./tool-call">工具调用</a>的详情区，展示这次调用改了什么。</li><li>要做「AI 提议的编辑逐条取舍 + 应用」：用<a href="./table">表格</a>的选择机制承载行级取舍， 单元格里放<a href="./checkbox">复选框</a>，页脚的计数与「应用」用<a href="./button">按钮</a>。 差异视图本身只读，不接这套交互。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>并排视图给足宽度：两列各自还要横向滚动，窄栏下单栏更好读，或者开 <code>wrap</code> 让长行折下来。</li><li>折叠阈值取三到五行：再少就一直在点展开，再多就等于没折。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>截断了却不渲 <code>truncation</code>：断掉的差异看着仍像一份完整差异，评审的人会以为自己看完了。</li><li>拿补丁算出来的差异去着色：那份文本是残缺的，跨行的记号一定切错。</li><li>用颜色作为变更类型的唯一线索：色觉障碍与高对比度模式下它就消失了。</li></ul>',48))])}const P=n(f,[["render",p]]);export{v as __pageData,P as default};
